<div class="module-page module-utilizador-form"><div class="form-panel panel"><div class="page-header"><div><h1>Editar Utilizador</h1><p>Dados, fotografia, senha, perfil e ramos de <?=htmlspecialchars($u['nome_utilizador'])?>.</p></div></div><?php if($erro):?><div class="erro"><?=htmlspecialchars($erro)?></div><?php endif;?><?php if($sucesso):?><div class="alert-sucesso"><?=htmlspecialchars($sucesso)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form-grid">
<div class="foto-edicao full"><div class="foto-edicao-preview"><?php if(!empty($u['foto'])):?><img src="<?=htmlspecialchars(app_file_url($u['foto']))?>" alt="Foto do utilizador"><?php else:?><span><?=htmlspecialchars(strtoupper(substr($u['nome_utilizador'],0,1)))?></span><?php endif;?></div><div><strong>Fotografia</strong><small>Escolha uma nova imagem para substituir a atual.</small><input type="file" name="foto" accept="image/jpeg,image/png,image/webp"></div></div>
