<label>Nova senha<input type="password" name="senha" placeholder="Deixe vazio para manter a atual"></label><label>Perfil<select required name="id_perfil"><?php foreach($perfis as $p):?><option value="<?=$p['id_perfil']?>" <?=$u['id_perfil']==$p['id_perfil']?'selected':''?>><?=htmlspecialchars($p['nome'])?></option><?php endforeach;?></select></label>
<label class="full">Ramos<select name="ramos[]" multiple size="5"><?php foreach($ramos as $r):?><option value="<?=$r['id_ramo']?>" <?=in_array((int)$r['id_ramo'],$ramosSelecionados,true)?'selected':''?>><?=htmlspecialchars(($r['sigla']?:$r['nome']).' — '.$r['nome'])?></option><?php endforeach;?></select></label>
<label>Estado<select name="estado"><option value="ATIVO" <?=$u['estado']==='ATIVO'?'selected':''?>>ATIVO</option><option value="INATIVO" <?=$u['estado']==='INATIVO'?'selected':''?>>INATIVO</option></select></label>
<div class="full actions"><button class="btn btn-primary">Guardar alterações</button><a class="btn btn-secondary" href="utilizadores.php">Voltar</a></div></form></div></div>
